bool includes(const Json&values,const Json&value){return std::find(values.begin(),values.end(),value)!=values.end();}
using Protections=std::vector<std::pair<std::string,Json>>;
Protections protections(const Json&scene,const Json&part){
 Protections result;for(const auto&socket:scene.value("sockets",Json::array())){if(!socket.value("enabled",true))continue;bool has_samples=false,named_by_end=false;const Json ends=socket.value("support_ends",Json::object());for(const auto&end:ends){if(!includes(end.value("part_ids",Json::array()),part["id"]))continue;named_by_end=true;double radius=number(end.value("required_depth_m",Json(.005)),"required_depth_m",0);if(radius<=0)fail("required_depth_m must be positive");for(const auto&point:end.value("samples",Json::array())){has_samples=true;result.push_back({socket["id"],sample_protection(scene,part,vector<3>(point,"support sample"),end.value("node",socket.value("node",Json(nullptr))),radius)});}}
  if(!has_samples&&(named_by_end||includes(socket.value("coverage",Json::object()).value("support_part_ids",Json::array()),part["id"]))){auto b=bounds(part);result.push_back({socket["id"],{{"shape","box"},{"min",{b[0],b[2],b[4]}},{"max",{b[1],b[3],b[5]}}}});}}
 if(result.size()>4096)fail("functional protection sample budget exceeded");
 return result;
}
bool intersects(const Json&first,const Json&second){auto b=region_bounds(second);for(size_t axis=0;axis<3;++axis)if(first["max"][axis].get<double>()<b.first[axis]||first["min"][axis].get<double>()>b.second[axis])return false;return true;}
Polygon clip_polygon(Polygon output,V3 low,V3 high){
 struct Plane{size_t axis;double bound;bool greater;};for(auto plane:std::vector<Plane>{{0,low[0],true},{0,high[0],false},{1,low[2],true},{1,high[2],false}}){auto source=output;output.clear();if(source.empty())break;auto previous=source.back();bool previous_inside=plane.greater?previous[plane.axis]>=plane.bound:previous[plane.axis]<=plane.bound;for(auto point:source){bool inside=plane.greater?point[plane.axis]>=plane.bound:point[plane.axis]<=plane.bound;if(inside!=previous_inside){double t=(plane.bound-previous[plane.axis])/(point[plane.axis]-previous[plane.axis]);output.push_back({previous[0]+t*(point[0]-previous[0]),previous[1]+t*(point[1]-previous[1])});}if(inside)output.push_back(point);previous=point;previous_inside=inside;}}return output;
}
bool support_volume_present(const Json&part,const Json&r){auto b=bounds(part);auto low=r["min"].get<V3>(),high=r["max"].get<V3>();for(size_t axis=0;axis<3;++axis)if(low[axis]<b[2*axis]-1e-10||high[axis]>b[2*axis+1]+1e-10)return false;for(const auto&cut:part.value("cuts",Json::array())){double overlap=std::min(high[1],cut["y_range"][1].get<double>())-std::max(low[1],cut["y_range"][0].get<double>());if(overlap<=1e-10)continue;auto polygon=clip_polygon(cut["polygon_xz"].get<Polygon>(),low,high);if(polygon.size()<3)continue;double sum=0;for(size_t i=0;i<polygon.size();++i){auto a=polygon[i],b=polygon[(i+1)%polygon.size()];sum+=a[0]*b[1]-b[0]*a[1];}if(std::abs(sum)>2e-12)return false;}return true;}
