double smootherstep(double value){double t=std::max(0.,std::min(1.,number(value,"smootherstep input")));return t*t*t*(t*(t*6-15)+10);}
double selection_weight(const std::string&part_id,const std::string&side,V3 point,const Json&s){if(side!="front"&&side!="back")fail("query side must be front or back");auto p=vector<3>(point,"point");auto selected=selection(s);return selected_weight(part_id,side,p,selected);}
double edge_distance(const Json&part,V3 point,std::string side){auto p=vector<3>(point,"point");auto b=bounds(part);if(side.empty())side=std::abs(p[1]-b[3])<=1e-10?"back":"front";if(side!="front"&&side!="back")fail("query side must be front or back");auto segments=surface_segments(part,side);double distance=std::numeric_limits<double>::infinity();for(const auto&s:segments)distance=std::min(distance,segment_distance({p[0],p[2]},s[0],s[1]));return distance;}
double edge_wear_weight(const Json&part,const std::string&side,V3 point,const Json&s){auto selected=selection(s);selected["width_m"]=number(selected.value("width_m",Json(.015)),"width_m",0);if(selected["width_m"].get<double>()<=0)fail("width_m must be positive");selected["amount"]=number(selected.value("amount",Json(1)),"amount",0,1);if(side!="front"&&side!="back")fail("query side must be front or back");auto p=vector<3>(point,"point");return edge_weight(part,side,p,selected,surface_segments(part,side));}
Json apply_operations(const Json&scene,const Json&operations,bool fine_breakup_validation){
 if(!operations.is_array()||operations.size()>64)fail("operations must be a list of at most 64 entries");
 std::map<std::string,const Json*> original_parts;for(const auto&part:scene.at("parts"))original_parts[part["id"]]=&part;if(original_parts.size()!=scene["parts"].size())fail("scene has duplicate part IDs");Json selected_operations=Json::array();std::map<std::string,size_t> counts;
 for(const auto&op:operations){if(!op.is_object()||!op.contains("part_id")||!op["part_id"].is_string()||!original_parts.count(op["part_id"].get<std::string>()))fail("operation must select an existing exact part_id");std::string id=op["part_id"];const auto&part=*original_parts.at(id);auto s=operation(op,part,fine_breakup_validation);selected_operations.push_back(s);if(s["type"]=="cut"||s["type"]=="crack"){size_t additional=s["type"]=="crack"?2+s["branches"].get<size_t>():1;if(!counts.count(id))counts[id]=part.value("cuts",Json::array()).size();counts[id]+=additional;if(counts[id]>12)fail("operation cut budget exceeds 12 per part");}}
 Json result=scene;if(selected_operations.empty())return result;if(!result.contains("metadata"))result["metadata"]=Json::object();if(!result["metadata"].contains("damage_operations"))result["metadata"]["damage_operations"]=Json::array();std::map<std::string,size_t> positions;for(size_t i=0;i<result["parts"].size();++i)positions[result["parts"][i]["id"]]=i;
 for(auto selected:selected_operations){size_t position=positions.at(selected["part_id"].get<std::string>());Json part=result["parts"][position];auto protected_regions=protections(result,part);for(const auto&p:protected_regions)selected["protected_regions"].push_back(p.second);Json report={{"type",selected["type"]},{"part_id",selected["part_id"]},{"side",selected["side"]},{"region",selected["region"]},{"seed",selected["seed"]},{"override_protection",selected.value("override_protection",false)}};
  auto append_report=[&](){result["metadata"]["damage_operations"].push_back(report);};
  if(selected["type"]=="edge_wear"){if(!part.contains("edge_wear"))part["edge_wear"]=Json::array();part["edge_wear"].push_back(edge_config(part,selected));result["parts"][position]=part;report["status"]="applied";report["geometry_changed"]=false;append_report();continue;}
  Json cutters=Json::array();
  if(selected["type"]=="crack"){cutters=crack_cutters(part,selected);report["profile_count"]=cutters.size();for(const auto&k:{"length_m","width_m","depth_m","center_xz","direction_xz","branches","segments"})report[k]=selected[k];report["profiles"]=Json::array();for(const auto&c:cutters){Json p=Json::object();for(const auto&k:{"polygon_xz","depth","role","centerline_xz"})p[k]=c[k];report["profiles"].push_back(p);}}
  else{auto c=cutter(part,selected);if(!c.is_null())cutters.push_back(c);}
  if(cutters.empty()){report["status"]="outside";report["reason"]="Selection does not intersect the requested exterior face with positive depth.";append_report();continue;}
  std::set<std::string> sockets;for(const auto&p:protected_regions)for(const auto&c:cutters)if(intersects(c,p.second))sockets.insert(p.first);bool user_protected=false;for(const auto&r:selected["protected_regions"])for(const auto&c:cutters)if(intersects(c,r))user_protected=true;
  if(!selected.value("override_protection",false)&&(!sockets.empty()||user_protected)){report["status"]="protected";report["protected_socket_ids"]=std::vector<std::string>(sockets.begin(),sockets.end());report["reason"]="Operation conservatively intersects a functional keep-out; explicit boolean override_protection=True is required.";append_report();continue;}
  Json carved=part;try{for(const auto&c:cutters)carved=carve_panel(carved,c["polygon_xz"],selected["side"],c["depth"]);}
  catch(const std::invalid_argument&error){if(selected["type"]=="crack")fail("crack could not apply every profile transactionally: "+std::string(error.what()));if(std::string(error.what())!="Cutter does not remove new panel material")throw;report["status"]="outside";report["reason"]=error.what();append_report();continue;}
  if(carved.contains("edge_wear")&&!carved["edge_wear"].empty()){Json configs=Json::array();for(const auto&config:carved["edge_wear"])configs.push_back(edge_config(carved,config));carved["edge_wear"]=configs;}result["parts"][position]=carved;
  report["status"]="applied";report["geometry_changed"]=true;
  if(selected["type"]=="crack"){report["depth"]=selected["depth_m"];report["through"]=false;report["region_method"]="complete_profiles_fully_contained";report["cut_indices"]=Json::array();for(size_t i=part.value("cuts",Json::array()).size();i<carved["cuts"].size();++i)report["cut_indices"].push_back(i);}
  else{report["depth"]=cutters[0]["depth"];report["through"]=cutters[0]["depth"].is_null();report["region_method"]="inscribed_polygon_prism_clipped_to_y_extent";}
  if(selected.value("override_protection",false)){auto invalidated=validate_supports(result);report["invalidated_socket_ids"]=invalidated.first;report["invalidated_grip_ids"]=invalidated.second;}append_report();
 }return result;
}
Json apply_operations(const Json&scene,const Json&operations){return apply_operations(scene,operations,false);}
